import{_ as s,o as t,c as e,a2 as a}from"./chunks/framework.BfI5QxtK.js";const E=JSON.parse('{"title":"Window snapping","description":"","frontmatter":{},"headers":[],"relativePath":"window-snapping.md","filePath":"window-snapping.md"}'),n={name:"window-snapping.md"};function h(o,i,d,r,l,p){return t(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="window-snapping" tabindex="-1">Window snapping <a class="header-anchor" href="#window-snapping" aria-label="Permalink to &quot;Window snapping&quot;">​</a></h1><p><a href="./configuration-reference">Configuration reference</a></p><p>With Bingux installed, drag a window toward an edge or press Super+Z to choose a layout. Bingux displays the picker; Gnoblin moves and resizes the window. The picker controls below belong to Bingux. Other shells can provide their own using the <a href="#shell-integration">integration API</a>.</p><p>This supports resizable Wayland and X11 windows. Minimum sizes still apply; fullscreen and fixed-size windows are excluded.</p><h2 id="use-the-picker" tabindex="-1">Use the picker <a class="header-anchor" href="#use-the-picker" aria-label="Permalink to &quot;Use the picker&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Result</th></tr></thead><tbody><tr><td>Drag toward the top centre</td><td>Show layouts</td></tr><tr><td>Release at the top edge</td><td>Fill the work area</td></tr><tr><td>Drag to a side or corner</td><td>Half or quarter screen</td></tr><tr><td>Release over a layout region</td><td>Snap to that region</td></tr><tr><td>Hold Ctrl while dragging</td><td>Select regions in the active layout</td></tr><tr><td>Super+Z</td><td>Choose a region for the focused window</td></tr><tr><td>Arrows/Tab, then Enter</td><td>Select with the keyboard</td></tr><tr><td>Escape</td><td>Cancel</td></tr><tr><td>Drag a snapped window away</td><td>Restore its original size</td></tr></tbody></table><p>Bingux saves layouts in <code>~/.config/bingux/snapping.ini</code>. It imports Tiling Shell layouts once when available; otherwise it supplies defaults.</p><p>Windows fill the usable part of the monitor, leaving room for panels that reserve space. See <a href="./session-settings#window-drag-boundary">drag boundaries</a> for overlap policy.</p><h2 id="shell-integration" tabindex="-1">Shell integration <a class="header-anchor" href="#shell-integration" aria-label="Permalink to &quot;Shell integration&quot;">​</a></h2><p>Use the <a href="./compositor-bridge">bridge socket</a> to supply a picker. Rectangles use logical desktop pixels. Read the work area from Gnoblin; it excludes space reserved by panels.</p><table tabindex="0"><thead><tr><th>Step</th><th>Message</th><th>What Gnoblin returns or does</th></tr></thead><tbody><tr><td>Watch drags</td><td><code>{&quot;op&quot;:&quot;window-drag&quot;}</code></td><td><code>window-drag</code> events with <code>active</code>, <code>serial</code>, <code>window</code>, pointer <code>x</code>/<code>y</code>, <code>modifiers</code>, <code>monitor</code> and <code>area</code></td></tr><tr><td>Offer regions</td><td><code>snap-offer</code></td><td>Tests the pointer against <code>hit</code> rectangles on release, then applies the matching <code>target</code></td></tr><tr><td>Ask about focus</td><td><code>{&quot;op&quot;:&quot;snap-context&quot;}</code></td><td><code>snap-context</code> with focused <code>window</code>, <code>monitor</code> and <code>area</code></td></tr><tr><td>Apply keyboard choice</td><td><code>snap-window</code></td><td>Moves and resizes the chosen window</td></tr></tbody></table><p>For example, after receiving an active drag with <code>serial: 7</code>, a shell can offer the left half of a 1920 × 1048 work area starting at <code>(0, 32)</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snap-offer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;serial&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;regions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;hit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">960</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;layout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;left-half&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>Build both rectangles from the current event&#39;s <code>area</code> and <code>monitor</code>; the numbers above only show the message shape. At most 128 regions may be offered. Each rectangle needs finite <code>x</code>, <code>y</code>, <code>width</code> and <code>height</code>; sizes must be 1–32768. Optional <code>control: true</code> requires Ctrl at release. Optional <code>maximize: true</code> maximizes the window instead of using <code>target</code> as its final size. On success the owner receives <code>{&quot;event&quot;:&quot;snap-completed&quot;,&quot;layout&quot;:&quot;left-half&quot;}</code>.</p><p>For a keyboard picker, request <code>snap-context</code>, let the user choose a rectangle inside its <code>area</code>, then send:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;op&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snap-window&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;window&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;42&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;monitor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;width&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">960</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;height&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>Use the returned window ID and monitor ID. Only one client owns a drag. Gnoblin rejects stale serials and targets outside the work area. Escape, disconnect or drag completion clears offers; the picker does not grab input during a drag.</p>',17)])])}const g=s(n,[["render",h]]);export{E as __pageData,g as default};
